 ],
 "unknowns": [
  "Why the route table fails to load in 1.5.1 (config change, missing file, startup ordering); no config diff or startup logs are available.",
  "Whether all gateway instances run 1.5.1 or only some; a partial rollout could explain why only part of the traffic fails.",
  "Whether the error ratio was still rising at the end of the window (last value was 25.8%).",
  "Whether other gateway routes besides /checkout and /products are affected."
 ],
 "recommended_actions": [
  {
   "action": "Roll back gateway to 1.4.2.",
   "rationale": "The errors began immediately after the 1.5.1 deploy and are tagged only with release 1.5.1.",
   "evidence_ids": [
    "ev-965d5c78fedd",
